const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const groups={warehouse:'石狩倉庫',factory:'発寒支店',carry:'管理担当持込','':'在庫場所が未設定'};
const fields=[['requester','依頼者・確認先'],['customer','顧客名'],['name','商品名'],['maker','メーカー'],['sku','品番'],['size','サイズ'],['condition','新古'],['quantity','数量'],['stock','在庫場所'],['note2','備考②']];
const columns=[['requester','依頼者・確認先'],['customer','顧客名'],['name','アイテム名'],['maker','メーカー'],['sku','品番'],['size','サイズ'],['condition','新古'],['quantity','数量'],['note2','備考②'],['operator','実行者'],['check','確認'],['entry','入力'],['check2','確認']];
let user,lists=[],candidates=[],current=null,dirty=false,busy=false,step=1,titleTouched=false,activeGroup='warehouse',board={bucket:'',page:1,q:'',from:'',to:''},boardData=null,selected=new Map(),targetScope=[],excluded=new Map(),scopeTotal=0,candidatePage=1,candidatePages=1,candidateTotal=0,candidateQuery='';
const SHEET_LIMIT=100,CAND_PAGE=20;
