const carryKind=pageQuery.get('carry');
const boardMode=pageQuery.get('board')==='1';
const popupMode=pageQuery.get('popup')==='1';
let viewingSources=false,viewingSheets=false,viewingTargets=false,sheetsClosingQuiet=false;
function boardReturnUrl(){if(pageQuery.get('history')==='1')return '/picking-history';const next=new URLSearchParams();next.set('bucket',pageQuery.get('bucket')||'drafts');for(const key of ['q','from','to','page']){const value=pageQuery.get(key);if(value)next.set(key,value)}return '/picking-board?'+next.toString()}
async function openFromBoard(){if($('#boardnote'))$('#boardnote').hidden=false;if($('#boardback')){$('#boardback').hidden=false;$('#boardback').href=boardReturnUrl()}const id=Number(pageQuery.get('list'));if(!id){location.replace(boardReturnUrl());return}await open(await api('/api/picking/'+id));message('保存した依頼を開きました。送信前の内容は修正して保存できます。')}
let carryDoc={day:'',version:0,rows:[]},carryDraft=[],carryDays=[],carryOpen=false,carryDirty=false;
function today(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function suggestedTitle(day){const m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(day||'');return m?`${m[1]}年${Number(m[2])}月${Number(m[3])}日 ピッキング依頼`:''}
function arrangeKind(rows){let warehouse=0,other=0;for(const r of rows||[]){if(r.stock==='warehouse')warehouse++;else if(r.stock==='factory'||r.stock==='carry')other++}if(warehouse)return 'mail';if(other)return 'local';return 'empty'}
function phaseOf(r,rows){if(!r)return '';if(r.status==='取消')return '取消';if(r.sentAt)return '手配完了（メール送信）';if(r.arrangedAt)return '手配完了（メール不要）';const kind=arrangeKind(rows||r.rows||[]);if(kind==='local')return 'メール不要・手配待ち';if(r.mailedAt)return 'メール作成済み・送信記録待ち';if(kind==='mail')return 'メール依頼が必要・メール未作成';return r.id?'保存済み・手配未完了':'未保存'}
function listFinished(r){return !!(r&&(r.sentAt||r.arrangedAt))}
async function api(url,data){const r=await fetch(url,data?{method:'POST',headers:{'Content-Type':'application/json','X-Desk-Request':'1'},body:JSON.stringify(data)}:{});const d=await r.json();if(!r.ok)throw Error(d.error||'処理に失敗しました。');return d}
function message(s){$('#message').textContent=s}
function mailStepAllowed(){return !!(current&&current.id&&current.status==='確定'&&!dirty)}
function syncControls(){if(boardData){$('#homeprev').disabled=boardData.page<=1;$('#homenext').disabled=boardData.page>=boardData.pages}const rows=current?allrows().length:0;if($('#stepnext'))$('#stepnext').disabled=false;if($('#stepblock'))$('#stepblock').hidden=true;syncAddRow();if(current&&step!==1&&$('#lane1sum'))$('#lane1sum').textContent=`指示書${current.sources.length}件・直接入力${current.manual.length}明細`;if(current&&step!==2&&$('#lane2sum'))$('#lane2sum').textContent=rows?groupBits():'内容確認へ進むと開きます';if(carryKind==='out'&&$('#carryprint'))$('#carryprint').disabled=!carryOutRows.length;syncPickButtons()}
function groupBits(){const rows=allrows();return ['warehouse','factory','carry'].map(k=>`${groups[k]}${rows.filter(r=>r.stock===k).length}明細`).join('／')}
function scrollWork(id){const el=document.getElementById(id);if(el)el.scrollIntoView({block:'start',behavior:'smooth'})}
async function run(fn){if(busy)return;busy=true;document.querySelectorAll('button').forEach(b=>b.disabled=true);try{message('');await fn()}catch(e){message(e.message)}finally{busy=false;document.querySelectorAll('button').forEach(b=>b.disabled=false);syncControls()}}
function editable(){return current&&current.status!=='取消'&&!listFinished(current)&&current.canEdit!==false}
function allrows(){return [...current.sources.flatMap(s=>s.rows),...current.manual.map(r=>({...r,sourceNumber:r.sourceNumber||'直接依頼'}))]}
function ageWrite(){return '<span class="agewrite">新<br>中</span>'}
function conditionCell(r){const blank=!String(r.condition||'').trim()||r.condition==='未指定';if(r.stock==='warehouse'||blank)return ageWrite();return esc(r.condition)}
function table(rows){return '<table><thead><tr>'+columns.map(([,label])=>`<th>${label}</th>`).join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+columns.map(([k])=>`<td>${k==='condition'?conditionCell(r):esc(r[k])}</td>`).join('')+'</tr>').join('')+'</tbody></table>'}
function previewRows(){const imported=current.sources.flatMap(s=>s.rows).filter(r=>r.stock===activeGroup).sort((a,b)=>String(a.customer).localeCompare(String(b.customer),'ja')||String(a.requester).localeCompare(String(b.requester),'ja'));const typed=current.manual.filter(r=>r.stock===activeGroup).map(r=>({...r,sourceNumber:r.sourceNumber||'直接依頼'}));return [...typed,...imported]}
function lineIssues(){const buckets={warehouse:[],factory:[],carry:[],'':[]};const put=r=>{const key=r.stock==='warehouse'||r.stock==='factory'||r.stock==='carry'?r.stock:'';buckets[key].push(r)};current.manual.forEach(r=>put({...r,sourceNumber:r.sourceNumber||'直接依頼'}));current.sources.flatMap(s=>s.rows).forEach(put);const rows=[...buckets.warehouse,...buckets.factory,...buckets.carry,...buckets['']],out=[];rows.forEach((r,i)=>{const where=`${i+1}行目（${groups[r.stock]||groups['']} / ${r.customer||'顧客名なし'} / ${r.name||'商品名なし'}）`;if(!r.requester)out.push(`${where}：依頼者・確認先を入力してください。`);if(!r.customer)out.push(`${where}：顧客名を入力してください。`);if(!r.name)out.push(`${where}：商品名を入力してください。`);if(!r.quantity)out.push(`${where}：数量を入力してください。`);if(!r.stock)out.push(`${where}：在庫場所が未設定です。取り込みを外し、指示書の在庫場所を直してから取り込み直してください。`)});if(!rows.length)out.unshift('明細を1行以上入力してください。');return out}
function cellInput(row,key){if(key==='condition')return `<select data-row="${esc(row.key)}" data-field="condition">${['未指定','新品','中古'].map(v=>`<option ${row.condition===v?'selected':''}>${v}</option>`).join('')}</select>`;if(key==='quantity')return `<input data-row="${esc(row.key)}" data-field="quantity" type="number" min="1" max="99999" step="1" value="${esc(row.quantity)}">`;if(key==='note')return `<textarea data-row="${esc(row.key)}" data-field="note" maxlength="1000" rows="2">${esc(row.note)}</textarea>`;return `<input data-row="${esc(row.key)}" data-field="${key}" type="text" maxlength="${key==='note2'?1000:300}" value="${esc(row[key]??'')}">`}
function previewTable(rows){const edit=editable();const entry=['requester','customer','name','maker','sku','size','quantity','note2'];return '<table><thead><tr>'+columns.map(([,label])=>`<th>${label}</th>`).join('')+(edit?'<th></th>':'')+'</tr></thead><tbody>'+rows.map(r=>{const typed=edit&&String(r.key||'').startsWith('manual:');const removable=edit&&(typed||String(r.key||'').startsWith('carry:'));return '<tr'+(typed?' class="exchange"':'')+'>'+columns.map(([k])=>`<td>${k==='condition'?conditionCell(r):typed&&entry.includes(k)?cellInput(r,k):esc(r[k])}</td>`).join('')+(edit?`<td>${removable?`<button type="button" class="drop" data-remove-manual="${esc(r.key)}">削除</button>`:''}</td>`:'')+'</tr>'}).join('')+'</tbody></table>'}
function bindManualEdits(root){root.querySelectorAll('[data-field]').forEach(el=>{const apply=()=>{const r=current.manual.find(r=>r.key===el.dataset.row);if(!r)return;r[el.dataset.field]=el.value;dirty=true;paintTabs();syncControls()};el.oninput=apply;el.onchange=apply});root.querySelectorAll('[data-remove-manual]').forEach(b=>b.onclick=()=>{if(!confirm('この行を削除しますか？'))return;current.manual=current.manual.filter(r=>r.key!==b.dataset.removeManual);dirty=true;paintGather();preview()})}
function paintTabs(){const rows=allrows();const defs=[['warehouse','石狩倉庫'],['factory','発寒支店'],['carry','管理担当持込']];if(rows.some(r=>!r.stock))defs.push(['','在庫場所未設定']);if(!defs.some(([k])=>k===activeGroup))activeGroup='warehouse';$('#grouptabs').innerHTML=defs.map(([k,label])=>`<button type="button" data-group="${esc(k)}" class="${k===activeGroup?'current':''}">${label} ${rows.filter(r=>r.stock===k).length}明細</button>`).join('');$('#grouptabs').querySelectorAll('button').forEach(b=>b.onclick=()=>{flushPreview();activeGroup=b.dataset.group;preview()})}
function preview(){const rows=previewRows();paintTabs();const problems=lineIssues().filter(s=>!s.startsWith('明細を1行以上'));$('#issues').innerHTML=problems.length?`<b>確認が必要な明細</b><ul>${problems.map(s=>`<li>${esc(s)}</li>`).join('')}</ul>`:'';$('#preview').innerHTML=rows.length?previewTable(rows):'<p>この区分の明細はありません。ほかの区分の入力は残っています。交換依頼は「交換依頼を追加」から、この一覧へ入力します。</p>';bindManualEdits($('#preview'));syncAddRow()}
function paintGather(){const edit=editable();if($('#fromsheets'))$('#fromsheets').hidden=true;if($('#loadcandidates'))$('#loadcandidates').hidden=!edit;paintSources();syncControls()}
function paintSources(){if(!current)return;const edit=editable();const imported=current.sources.reduce((n,s)=>n+(s.rows||[]).length,0);const lead=$('#sourceslead');if(lead)lead.textContent=(current.sources.length||current.manual.length)?`指示書${current.sources.length}件・${imported}明細、交換依頼${current.manual.length}明細です。下は倉庫へ渡す一覧です。`:'まだ明細がありません。指示書を取り込むか、交換依頼の行を追加してください。';const sheetBtn=$('#opensheets');if(sheetBtn)sheetBtn.textContent=`指示書の内訳 ${current.sources.length}件`;const chip=$('#sourcechips');if(chip){chip.innerHTML=current.sources.length?current.sources.map(s=>`<div class="candidate"><span><b>${esc(s.number)}　${esc(s.customer||'')}</b><small>${(s.rows||[]).length}明細</small></span>${edit?`<button type="button" data-remove-source="${s.id}">取り込みを外す</button>`:''}</div>`).join(''):'<p>取り込み済みの指示書はありません。</p>';chip.querySelectorAll('[data-remove-source]').forEach(b=>b.onclick=()=>{current.sources=current.sources.filter(s=>s.id!==+b.dataset.removeSource);dirty=true;paintSources();preview();paintLanes();run(async()=>{await loadCandidatePage(true);if(!$('#message').textContent)message('この依頼から外しました。指示書の作業状況は変えていません。作成画面のほかの入力は残しています。')})})}const defs=[['warehouse','石狩倉庫'],['factory','発寒支店'],['carry','管理担当持込']];const rowsAll=allrows();if(rowsAll.some(r=>!r.stock))defs.push(['','在庫場所未設定']);if(!defs.some(([k])=>k===activeGroup))activeGroup='warehouse';const tabs=$('#sourcegroups');if(tabs){tabs.innerHTML=defs.map(([k,label])=>`<button type="button" data-group="${esc(k)}" class="${k===activeGroup?'current':''}">${label} ${rowsAll.filter(r=>r.stock===k).length}明細</button>`).join('');tabs.querySelectorAll('button').forEach(b=>b.onclick=()=>{flushSourcePreview();flushPreview();activeGroup=b.dataset.group;paintSources();preview()})}const shown=previewRows();const view=$('#sourcepreview');if(view){view.innerHTML=shown.length?previewTable(shown):'<p>この区分の明細はありません。交換があるときは「交換依頼を追加」で行を足して入力します。</p>';bindManualEdits(view)}const add=$('#sourceadd');if(add){add.hidden=!edit;add.disabled=activeGroup==='carry'||activeGroup===''}}
function showImported(){if(!current)return;flushInputs();paintSources();const dlg=$('#sourcedialog');if(dlg&&!dlg.open)dlg.showModal()}
function hideImported(){const dlg=$('#sourcedialog');if(dlg&&dlg.open)dlg.close()}
function closeSheetsQuiet(){viewingSheets=false;sheetsClosingQuiet=true;const dlg=$('#sheetsdialog');if(dlg&&dlg.open)dlg.close();sheetsClosingQuiet=false}
function paintSheetBreakdown(){if(!current)return;const edit=editable();const sheetBtn=$('#opensheets');if(sheetBtn)sheetBtn.textContent=`指示書の内訳 ${current.sources.length}件`;const box=$('#sheetlines');if(!box)return;if(!current.sources.length){box.innerHTML='<p>この一覧に入っている指示書はありません。作成ボタンで取り込むと、ここで依頼を外せます。</p>';return}box.innerHTML=current.sources.map(s=>`<div class="candidate"><span><b>${esc(s.number)}　${esc(s.customer||'')}</b><small>${(s.rows||[]).length}明細</small></span>${edit?`<button type="button" data-drop-sheet="${s.id}">この依頼から除外</button>`:''}</div>`).join('');box.querySelectorAll('[data-drop-sheet]').forEach(b=>b.onclick=()=>dropSheet(+b.dataset.dropSheet))}
function dropSheet(id){if(!current||!editable())return;const s=current.sources.find(x=>x.id===id);if(!s)return;flushPreview();current.sources=current.sources.filter(x=>x.id!==id);excluded.set(id,{id:s.id,version:s.version,number:s.number,customer:s.customer||''});dirty=true;paintSheetBreakdown();preview();paintLanes();paintGather();message(`${s.number}をこの依頼から外しました。一覧の明細も外しています。作業状況は変えていません。`)}
function showSheets(){if(!current)return;flushInputs();viewingSheets=true;paintSheetBreakdown();const dlg=$('#sheetsdialog');if(dlg&&!dlg.open)dlg.showModal()}
function showTargets(){if(!current)return;const box=$('#candidatebox');const dlg=$('#targetdialog');const host=dlg&&dlg.querySelector('.dialogbody');if(box&&host&&box.parentElement!==host)host.appendChild(box);if(box)box.hidden=false;viewingTargets=true;if(dlg&&!dlg.open)dlg.showModal();return run(()=>loadCandidatePage(true))}
function hideTargets(){viewingTargets=false;const dlg=$('#targetdialog');if(dlg&&dlg.open)dlg.close();if($('#candidatebox'))$('#candidatebox').hidden=true}
function hideSheets(){const dlg=$('#sheetsdialog');const was=viewingSheets||!!(dlg&&dlg.open);viewingSheets=false;if(dlg&&dlg.open)dlg.close();if(!was)return;paintLanes();paintGather();preview();pinCounts()}
function showSources(){if(!current)return;flushInputs();viewingSources=true;$('#editor').hidden=true;$('#sourcescreen').hidden=false;paintSources();const el=document.getElementById('sourcescreen');if(el)el.scrollIntoView({block:'start',behavior:'smooth'})}
function hideSources(){viewingSources=false;viewingSheets=false;if($('#sourcescreen'))$('#sourcescreen').hidden=true;closeSheetsQuiet();if($('#editor'))$('#editor').hidden=false;paintLanes();paintGather();preview();pinCounts()}
function syncAddRow(){const btn=$('#addrow');if(!btn||!current)return;btn.hidden=!editable();btn.disabled=!editable()}
function takeItems(){const have=new Set((current?.sources||[]).map(s=>s.id));return targetScope.filter(s=>s&&!excluded.has(s.id)&&!have.has(s.id))}
function syncPickButtons(){const items=current?takeItems():[];const room=SHEET_LIMIT-(current?.sources.length||0);const over=items.length>room;const btn=$('#gatherall');if(btn){btn.textContent='指示書を取り込む';btn.disabled=!current||!editable()||!items.length}const review=$('#reviewtargets');if(review){review.hidden=!editable();review.disabled=!editable()}const limit=$('#targetlimit');if(limit){limit.hidden=!over;if(over)limit.textContent=`対象は${items.length}件です。1つのリストに入れられる指示書は${SHEET_LIMIT}件までです。先頭の一部は取り込みません。残り${items.length-room}件を今回の依頼から除外するか、リストを分けてください。`}const trim=$('#excludeoverflow');if(trim){trim.hidden=!(current&&editable()&&over);if(over)trim.textContent=`上限を超えた${items.length-room}件を今回の依頼から除外`}if($('#candprev')){$('#candprev').disabled=candidatePage<=1;$('#candnext').disabled=candidatePage>=Math.max(1,candidatePages)}}
function paintExcluded(){const box=$('#excludedbox');if(!box)return;if(!excluded.size){box.innerHTML='<p class="hint">今回の依頼から外した指示書はありません。</p>';return}box.innerHTML=`<p>除外 ${excluded.size}件。作業状況は変えていません。この依頼だけの除外で、恒久的な対象外にはなりません。</p>`+[...excluded.values()].map(s=>`<span class="exchip">${esc(s.number)} ${esc(s.customer||'')}<button type="button" data-include="${s.id}">除外をやめる</button></span>`).join('');box.querySelectorAll('[data-include]').forEach(b=>b.onclick=()=>includeSheet(+b.dataset.include))}
function paintCandidates(){if(!current)return;const items=takeItems();const counts=$('#targetcounts');if(counts)counts.textContent=items.length?`取り込み対象：${items.length}件`:'取り込み対象の指示書はありません';paintExcluded();const start=candidateTotal?(candidatePage-1)*CAND_PAGE+1:0;const end=candidateTotal?start+candidates.length-1:0;if($('#candpager'))$('#candpager').textContent=candidateTotal?`${start}–${end}件目 / 表示${candidateTotal}件（対象全体 ${scopeTotal}件）`:`表示0件 / 対象全体 ${scopeTotal}件`;const empty=candidateQuery?'<p class="hint">この検索では表示がありません。取り込み対象は、検索前の対象から除外分を除いたままです。</p>':(scopeTotal?'<p class="hint">このページに表示する指示書はありません。</p>':'<p class="hint">取り込み対象の指示書はありません。交換依頼は、作成画面から入力してピッキングリストを作れます。</p>');$('#candidates').innerHTML=candidates.map(c=>{const off=excluded.has(c.id);return `<div class="candidate${off?' excluded':''}"><span><b>${esc(c.number)}　${esc(c.customer)}</b><small>本担当者：${esc(c.owner)} ／ マーク出荷日：${esc(c.date)||'未設定'} ／ 作業状況：${esc(c.status)} ／ ピッキング依頼：未作成${off?' ／ 今回の依頼から除外中':''}</small></span><button type="button" data-exclude="${c.id}">${off?'除外をやめる':'今回の依頼から除外'}</button></div>`}).join('')||empty;$('#candidates').querySelectorAll('[data-exclude]').forEach(b=>b.onclick=()=>{const id=+b.dataset.exclude;if(excluded.has(id))includeSheet(id);else excludeSheet(id)});syncPickButtons()}
function excludeSheet(id){const s=targetScope.find(x=>x.id===id)||candidates.find(x=>x.id===id);if(!s)return;excluded.set(id,{id:s.id,version:s.version,number:s.number,customer:s.customer||''});paintCandidates();message(`${s.number}を今回の依頼から外しました。作業状況は変えていません。`)}
function includeSheet(id){const s=excluded.get(id);excluded.delete(id);paintCandidates();message(s?`${s.number}を対象に戻しました。`:'対象に戻しました。')}
function excludeOverflow(){const items=takeItems();const room=SHEET_LIMIT-(current?.sources.length||0);if(items.length<=room)return;const drop=items.slice(room);drop.forEach(s=>excluded.set(s.id,{id:s.id,version:s.version,number:s.number,customer:s.customer||''}));paintCandidates();message(`上限を超えた${drop.length}件を、今回の依頼から外しました。マーク出荷日が遅い方からです。作業状況は変えていません。恒久的な対象外ではありません。残った${items.length-drop.length}件で作成できます。`)}
function gatherAll(){return run(async()=>{const items=takeItems();if(!items.length)throw Error('今回取り込める指示書はありません。交換依頼は、内容確認の一覧から追加できます。除外している場合は、除外をやめると対象に戻ります。');const room=SHEET_LIMIT-(current.sources.length||0);if(items.length>room)throw Error(`対象は${items.length}件です。1つのリストに入れられる指示書は${SHEET_LIMIT}件までです。いま追加できるのは${room}件です。先頭の一部は取り込んでいません。残り${items.length-room}件を今回の依頼から除外するか、リストを分けてください。`);const data=await api('/api/picking/gather',{items:items.map(s=>({id:s.id,version:s.version}))});const added=data.added||[];for(const s of added){if(!current.sources.some(x=>x.id===s.id))current.sources.push(s)}if(added.length)dirty=true;paintGather();preview();paintLanes();await loadCandidatePage(true);const failed=data.failed||[];if(failed.length)throw Error(`作成中の明細に入れた指示書は${added.length}件です。入れられなかった指示書は${failed.length}件です。\n${failed.map(f=>`${f.number||('指示書 '+(f.id??''))}：${f.reason}`).join('\n')}\n入れた分は、まだ保存・確定・送信にはなっていません。指示書の作業状況は変えていません。表示のあとに増えた指示書は、入れていません。`);const unset=added.some(s=>(s.rows||[]).some(r=>!r.stock));message(unset?`対象${added.length}件を作成中の明細に入れました。まだ保存も確定もしていません。指示書の作業状況は変えていません。在庫場所を判定できない明細があります。`:`対象${added.length}件を作成中の明細に入れました。まだ保存も確定もしていません。指示書の作業状況は変えていません。交換依頼は「交換依頼を追加」を押すと、この一覧の先頭に入力欄が出ます。`)})}
async function loadCandidatePage(refreshScope){if(!current)return;const q=($('#candidateSearch')&&$('#candidateSearch').value||'').trim();candidateQuery=q;const body={q,page:candidatePage,except:(current.sources||[]).map(s=>s.id)};if(refreshScope)body.scope=true;const data=await api('/api/picking/candidates',body);candidates=data.items||[];candidateTotal=data.total||0;candidatePages=data.pages||1;candidatePage=data.page||1;if(refreshScope){const prev=new Set(targetScope.map(s=>s.id));const next=data.scope||[];const grown=prev.size?next.filter(s=>!prev.has(s.id)):[];targetScope=next;scopeTotal=targetScope.length;const ids=new Set(targetScope.map(s=>s.id));const gone=[...excluded.values()].filter(s=>!ids.has(s.id));gone.forEach(s=>excluded.delete(s.id));const notes=[];if(grown.length)notes.push(`対象が${grown.length}件増えました。作成ボタンを押すまで、明細には入りません。`);if(gone.length)notes.push(`除外していた${gone.length}件は、もう対象にありません。`);if(notes.length)message(notes.join(''))}paintCandidates()}
function paintLocalActions(rows){const box=$('#localactions');if(!box)return;const bits=[];for(const key of ['factory','carry']){const n=rows.filter(r=>r.stock===key).length;if(n)bits.push(`<button type="button" data-local-print="${key}">${groups[key]}を印刷（${n}明細）</button>`)}if(bits.length)bits.push('<button type="button" id="localexcel">Excelを出力</button>');box.innerHTML=bits.join('');box.querySelectorAll('[data-local-print]').forEach(b=>b.onclick=()=>printGroup(b.dataset.localPrint));const excel=box.querySelector('#localexcel');if(excel)excel.onclick=()=>{$('#download').click()}}
function paintMail(){const rows=allrows();const counts=Object.entries(groups).filter(([k])=>k!==''||rows.some(r=>!r.stock)).map(([k,v])=>`${v} ${rows.filter(r=>r.stock===k).length}明細`).join('、');const ready=current.status==='確定'&&!dirty;const kind=arrangeKind(rows);const mailed=!!current.mailedAt,sent=!!current.sentAt,arranged=!!current.arrangedAt;const mailMode=kind==='mail',localMode=kind==='local';const dest=mailMode?'石狩倉庫。下のメールアドレスです。':localMode?'石狩倉庫の明細がないため、メールは不要です。':'明細がありません。';$('#mailsummary').innerHTML=`<b>リスト番号</b><span>${esc(current.number||'保存すると付きます')}</span><b>保存名</b><span>${esc(current.title)}</span><b>依頼日</b><span>${esc(current.date)}（マーク出荷日ではありません）</span><b>明細</b><span>${esc(counts)}（合計 ${rows.length}明細）</span><b>手配</b><span>${esc(dest)}</span><b>添付Excel</b><span>${mailMode?'石狩倉庫・発寒支店・管理担当持込の3シートです。表示中のタブだけではありません。':'メール添付はありません。明細がある区分を印刷・出力します。'}</span><b>状態</b><span>${esc(phaseOf(current,rows))}</span>`;$('#mailpanel').hidden=!ready||!mailMode||sent||arranged;$('#sendmail').hidden=!ready||!mailMode||sent||arranged;$('#sendmail').textContent=current.mailNeedsRecreate?'修正した内容でメールを作り直す':mailed&&!sent?'Thunderbirdで依頼メールを開き、作業中にする':'Thunderbirdで依頼メールを開く';$('#sendmail').classList.toggle('primary',ready&&mailMode&&!sent&&!arranged);const sentNote=$('#sentdone');if(sentNote){sentNote.hidden=!sent;sentNote.textContent=sent?`${current.sentBy||''} が ${current.sentAt} にThunderbirdで依頼メールを開き、未着手の指示書を作業中にしました。この記録は、届けたことの自動確認ではありません。`:'';}const local=$('#localpanel');if(local)local.hidden=!ready||!localMode||sent;paintLocalActions(rows);const recordBtn=$('#arrangerecord');if(recordBtn){recordBtn.hidden=arranged||current.canEdit===false;recordBtn.classList.toggle('primary',localMode&&!arranged&&current.canEdit!==false)}const done=$('#arrangedone');if(done){done.hidden=!arranged;done.textContent=arranged?`${current.arrangedBy||''} が ${current.arrangedAt} にメール不要の手配を記録しました。`:''}}
function paintMore(){const reopen=false;const history=!!current.id;const output=current.status==='確定';const cancel=!!current.id&&current.status!=='取消'&&!listFinished(current)&&current.canEdit!==false;$('#reopen').hidden=!reopen;$('#history').hidden=!history;$('#download').hidden=!output;$('#print').hidden=!output;$('#cancel').hidden=!cancel;$('#owneradmin').hidden=true;$('#moreactions').hidden=!(reopen||history||output||cancel)}
function placeList(){const list=$('#listview');const host=$('#step1');if(list&&host&&list.parentElement!==host)host.appendChild(list)}
function paintLanes(){const edit=editable();const open=step;placeList();const count=allrows().length;const allow=mailStepAllowed();$('#lane1body').hidden=open!==1;$('#lane1').classList.toggle('open',open===1);$('#lane1').setAttribute('aria-expanded',open===1?'true':'false');$('#lane1sum').hidden=open===1;$('#lane1sum').textContent=`指示書${current.sources.length}件・直接入力${current.manual.length}明細`;$('#fix1').hidden=open===1||!edit;$('#view1').hidden=open===1||edit;if($('#stepnext'))$('#stepnext').hidden=true;$('#finalize').hidden=!(edit&&open===1);$('#lane3body').hidden=open!==3;$('#lane3').classList.toggle('open',open===3);$('#lane3').setAttribute('aria-expanded',open===3?'true':'false');$('#lane3sum').hidden=open===3;const kind=arrangeKind(allrows());$('#lane3sum').textContent=!allow?'保存すると操作できます':current.sentAt?'メール送信で手配完了':current.arrangedAt?'メール不要で手配完了':kind==='local'?'メールは不要です。手配の記録はまだです':current.mailedAt?'メール作成画面を開いた記録があります':'保存済みです。メールはまだ作成していません';$('#lane3wait').hidden=!(open===3&&!allow);$('#step3').hidden=!allow;$('#gohome').hidden=!(listFinished(current)&&open===3);$('#gohome').textContent=boardMode?'一覧へ戻る':'次の依頼を作る';const notes={1:'下の表が、内容確認の一覧です。',2:'保存すると、下の依頼・手配の欄が開きます。保存は手配完了ではありません。',3:current.sentAt?'メール送信で手配完了しました。':current.arrangedAt?'メール不要の手配を記録しました。':kind==='local'?'石狩倉庫の明細がないため、メールは不要です。必要なリストを印刷・出力してから、手配したことを記録してください。':current.mailedAt?'メール作成画面を開いた記録があります。Thunderbirdで送信したあと、「送信したことを記録」を押してください。':'宛先を確認し、Thunderbirdで依頼メールを開きます。送信はThunderbird側の操作です。'};$('#stepnote').textContent=notes[open]||'';$('#savedraft').hidden=true;$('#finalize').textContent=current.id?'変更を保存':'保存する';$('#mailnext').hidden=!(edit&&open===1);$('#mailnext').textContent=kind==='local'?'保存して手配へ':'保存してメール作成へ';syncControls()}
function paintEditor(){const edit=editable();$('#carrydesk').hidden=true;$('#carryin').hidden=true;$('#library').hidden=false;$('#library').classList.add('working');viewingSources=false;viewingSheets=false;if($('#sourcescreen'))$('#sourcescreen').hidden=true;closeSheetsQuiet();hideImported();$('#editor').hidden=false;$('#homefocus').hidden=true;const fresh=!current.id;$('#number').textContent=current.number||'';$('#editorheading').textContent=current.sentAt?'メール送信で手配完了した依頼':current.arrangedAt?'メール不要で手配完了した依頼':current.id?'保存した倉庫依頼':'';$('#phaselabel').textContent=fresh?'':phaseOf(current,allrows());$('#number').hidden=fresh;$('#editorheading').hidden=fresh;$('#phaselabel').hidden=fresh;const workhead=$('#number').closest('.workhead');if(workhead)workhead.hidden=fresh;$('#title').value=current.title||'';$('#date').value=current.date||'';$('#status').textContent=fresh?'':phaseOf(current,allrows());$('#status').hidden=fresh;$('#title').disabled=!edit;$('#date').disabled=!edit;if($('#candidatebox')&&!viewingTargets)$('#candidatebox').hidden=true;$('#back').hidden=boardMode||!current.id;$('#back').textContent='新しい依頼に切り替える';if($('#boardback')){$('#boardback').hidden=!boardMode;if(boardMode)$('#boardback').href=boardReturnUrl()}if($('#boardnote'))$('#boardnote').hidden=!boardMode;if($('#startnew'))$('#startnew').hidden=true;$('#historypanel').hidden=true;paintLanes();paintGather();preview();paintMail();paintMore();pinCounts();if(popupMode){$('#library').hidden=true;$('#back').hidden=true;if($('#boardback'))$('#boardback').hidden=true;if($('#boardnote'))$('#boardnote').hidden=true}}
function resumeStep(value){return listFinished(value)||value.status==='取消'?3:1}
function pendingNote(){if(dirty&&excluded.size)return '保存していない入力と、今回の依頼から外した指示書があります。';if(dirty)return '保存していない入力があります。';if(excluded.size)return `今回の依頼から外した指示書が${excluded.size}件あります。除外は保存されていません。`;return ''}
function confirmSwitch(action){const note=pendingNote();if(!note)return true;return confirm(`${note}破棄して${action}か？${dirty&&editable()?'戻らない場合は、このまま途中保存できます。':''}`)}
function blankList(){const day=today();return {title:suggestedTitle(day),date:day,status:'下書き',sources:[],manual:[],canEdit:true}}
function resetPicks(){targetScope=[];excluded.clear();scopeTotal=0;candidatePage=1;candidatePages=1;candidateTotal=0;candidateQuery='';if($('#candidateSearch'))$('#candidateSearch').value=''}
async function openBlank(){resetPicks();current=blankList();dirty=false;titleTouched=false;activeGroup='warehouse';step=1;message('');paintEditor();await loadCandidatePage(true)}
function open(value){resetPicks();current=structuredClone(value);current.sources=current.sources||[];current.manual=current.manual||[];dirty=false;titleTouched=(current.title||'')!==suggestedTitle(current.date);activeGroup='warehouse';step=resumeStep(current);message('');paintEditor();scrollWork(step===1?'editorheading':'lane'+step+'h');if(editable()&&step===1)return loadCandidatePage(true)}
function actionName(r){if(r.phase==='取消')return '取消内容を確認';if(r.phase==='メール作成済み・送信記録待ち')return '送信確認へ';if(r.phase==='メール不要・手配待ち')return '手配の記録へ';if((r.phase==='メール依頼が必要・メール未作成'||r.phase==='保存済み・手配未完了')&&r.canEdit!==false)return '編集を続ける';return '依頼内容を確認'}
function progressText(r){return r.phase||phaseOf(r)}
function rangeText(data){if(data.bucket==='sheets'){const parts=[];if(data.from&&data.to)parts.push(`マーク出荷日 ${data.from} ～ ${data.to}`);else if(data.from)parts.push(`マーク出荷日 ${data.from} 以降`);else if(data.to)parts.push(`マーク出荷日 ${data.to} まで`);if(data.q)parts.push(`検索「${data.q}」`);if(!parts.length)return `未取り込みの指示書 ${data.counts.sheets}件です。指示書の件数で、手入力の交換依頼は含みません。`;return `${parts.join('、')}で ${data.total}件。未取り込みの指示書は全体で ${data.counts.sheets}件です。`}if(data.q)return `検索「${data.q}」のリスト ${data.total}件。上の件数は検索前のリスト数です。`;return ''}
function hintFor(bucket){if(bucket==='waiting')return '保存済み・手配未完了は、メール待ちと、メール不要の手配待ちの両方です。削除済みと手配完了済みは含みません。';if(bucket==='sheets')return '未取り込みは、未着手で商品明細があり、有効なリストに入っていない指示書です。下書き・サンプル・作業中・発送済・完了は含めません。日付を指定していないときは、過去や将来のマーク出荷日も含みます。日付は指示書のマーク出荷日で、依頼日ではありません。作成途中のリストに入っている指示書はここには出ません。続きは作成途中から開きます。依頼準備済みではありません。';if(bucket==='cancelled')return '';if(bucket==='sent')return '手配完了は、メール送信またはメール不要の手配を記録したリストです。';if(bucket==='drafts')return '作成途中は、下書きのリストです。編集を続けると、途中の内容から再開します。';return ''}
function paintSelected(){const box=$('#homeselected');if(!selected.size||board.bucket!=='sheets'){box.innerHTML='';$('#clearselected').hidden=true;return}const names=[...selected.values()].map(s=>esc(s.number)).join('、');box.innerHTML=`<p>選択中 <b>${selected.size}件</b>。検索条件を変えても選択は残ります。選択しただけでは保存・確定・送信にはなりません。</p><p class="hint">${names}</p>`;$('#clearselected').hidden=false}
function paintHome(){const data=boardData;if(!data)return;const waiting=data.counts.waiting||0;$('#homecards').innerHTML=`<button type="button" class="homecard" id="openwaiting" title="保存した依頼を確認・編集できます。手配完了前の件数です"><span>保存済み・手配未完了</span><strong>${waiting}件</strong><small>この画面の上に開きます</small></button>`;const openWaiting=$('#openwaiting');if(openWaiting)openWaiting.onclick=()=>openSaved('waiting');if($('#homefocus'))$('#homefocus').hidden=true;pinCounts()}
async function loadBoard(){const data=await api('/api/picking/board',{bucket:board.bucket,q:board.q,from:board.from,to:board.to,page:board.page});if(data.bucket==='sent'||data.bucket==='cancelled'){board.bucket='sheets';board.page=1;return loadBoard()}board.bucket=data.bucket;board.page=data.page;boardData=data;paintHome();pinCounts()}
async function refreshBoard(){if(carryKind)return;try{await loadBoard()}catch(e){}}
async function openList(id){if(!confirmSwitch('このリストを開きます'))return;const value=await api('/api/picking/'+id);return open(value)}
async function startFromSelection(){if(!confirmSwitch('新しい依頼を作ります'))return;if(!selected.size)throw Error('指示書を1件以上選んでください。');if(selected.size>100)throw Error('1つのリストに入れられる指示書は100件までです。選択を分けてください。');const sources=[];const failed=[];for(const item of [...selected.values()]){try{sources.push(await api('/api/picking/preview',{id:item.id,version:item.version}))}catch(e){failed.push(`${item.number}：${e.message}`);selected.delete(item.id)}}await loadBoard();if(failed.length)throw Error(failed.join('\n')+'\nこの指示書は選択から外しました。ほかの選択は残しています。依頼はまだ作っていません。');const day=today();selected.clear();excluded.clear();candidatePage=1;current={title:suggestedTitle(day),date:day,status:'下書き',sources,manual:[],canEdit:true};dirty=true;titleTouched=false;activeGroup='warehouse';step=1;paintEditor();await loadCandidatePage();scrollWork('editorheading');const unset=sources.some(s=>s.rows.some(r=>!r.stock));message(unset?'指示書を入れました。まだ保存も確定もしていません。在庫場所を判定できない明細があります。取り込みを外し、指示書の在庫場所を直してから取り込み直してください。':`指示書${sources.length}件を入れました。まだ保存も確定もしていません。`)}
function startDirect(){if(dirty&&!confirm('保存していない入力を破棄して、交換依頼の入力を開きますか？'))return;const day=today();const row={key:'manual:'+crypto.randomUUID(),requester:'マーク',customer:'',name:'',maker:'',sku:'',size:'',condition:'未指定',quantity:1,stock:'warehouse',note2:'',sourceNumber:'直接依頼'};current={title:suggestedTitle(day),date:day,status:'下書き',sources:[],manual:[row],canEdit:true};dirty=true;titleTouched=false;activeGroup='warehouse';step=1;message('指示書のない交換依頼です。この一覧で入力します。依頼者は「マーク」です。管理担当持込の入力とは別です。まだ保存していません。');paintEditor();const el=$('#preview').querySelector(`[data-row="${CSS.escape(row.key)}"]`);if(el)el.focus()}
function sameField(a,b){return String(a??'')===String(b??'')}
function flushHead(){if(!current)return;const title=$('#title').value,day=$('#date').value;if(!sameField(current.title,title)||!sameField(current.date,day))dirty=true;current.title=title;current.date=day}
function flushPreview(){$('#preview').querySelectorAll('[data-field]').forEach(el=>{const r=current.manual.find(r=>r.key===el.dataset.row);if(!r)return;if(!sameField(r[el.dataset.field],el.value)){r[el.dataset.field]=el.value;dirty=true}})}
function flushManualBrief(){const root=$('#manualbrief');if(!root)return;root.querySelectorAll('[data-field]').forEach(el=>{const r=current.manual.find(r=>r.key===el.dataset.row);if(r)r[el.dataset.field]=el.value})}
function flushSourcePreview(){const root=$('#sourcepreview');if(!root||!current)return;root.querySelectorAll('[data-field]').forEach(el=>{const r=current.manual.find(r=>r.key===el.dataset.row);if(!r)return;if(!sameField(r[el.dataset.field],el.value)){r[el.dataset.field]=el.value;dirty=true}})}
function flushInputs(){flushHead();flushPreview();flushSourcePreview()}
function goStep(n,scroll){if(!current||n===step||n<1||n>3)return;flushInputs();if(n===3&&!mailStepAllowed()){message(arrangeKind(allrows())==='local'?'変更を保存すると、手配へ進めます。保存は手配完了ではありません。':'変更を保存すると、メール作成へ進めます。保存は送信ではありません。');return}step=n;paintEditor();if(scroll)scrollWork('lane'+n+'h');if(n===1&&editable())run(()=>loadCandidatePage(true))}
function confirmSize(){flushInputs();const blank=current.manual.filter(r=>!String(r.size||'').trim());if(!blank.length)return true;const lines=blank.map(r=>`${r.customer||'顧客名なし'} / ${r.name||'商品名なし'}`).join('\n');return confirm(`サイズが未入力の直接入力が${blank.length}行あります。\n${lines}\nこのまま登録しますか？`)}
function needsSave(){return !!(current&&(!current.id||dirty))}
function checkedForSave(){flushInputs();if(!confirmSize())return false;const problems=lineIssues();if(problems.length){preview();message(problems.slice(0,8).join('\n'));return false}return true}
async function save(){flushInputs();let acknowledgeMailChange=false;if(current.mailedAt||current.mailNeedsRecreate){const local=arrangeKind(allrows())==='local';acknowledgeMailChange=confirm(local?'石狩倉庫の明細がなくなります。Thunderbirdで開いている古い依頼メールを破棄してください。新しいメールは作りません。すでに送信している場合は変更を保存せず、依頼メールを開くボタンで作業中にしてください。':'内容を変更したため、メールの作り直しが必要です。Thunderbirdで開いている古い依頼メールを破棄してください。すでに送信している場合は変更を保存せず、依頼メールを開くボタンで作業中にしてください。');if(!acknowledgeMailChange)return false}const value=await api('/api/picking/save',{id:current.id,version:current.version,title:current.title,date:current.date,status:'確定',acknowledgeMailChange,sources:current.sources.map(s=>({id:s.id,version:s.version})),manual:current.manual});current=value;dirty=false;paintEditor();await refreshBoard();if(editable()&&step===1)await loadCandidatePage(true);return value}
function loadCandidateList(){candidatePage=1;return run(()=>loadCandidatePage(true))}
function beginNew(){if(!confirmSwitch('新しい依頼に切り替えます'))return;return run(async()=>{await openBlank();scrollWork('editorheading')})}
if($('#startnew'))$('#startnew').onclick=beginNew;
$('#homesearch').onclick=()=>run(async()=>{board.q=$('#homeq').value.trim();if(board.bucket==='sheets'){board.from=$('#homefrom').value;board.to=$('#hometo').value}board.page=1;await loadBoard()});
$('#homeclear').onclick=()=>run(async()=>{board.q='';board.from='';board.to='';board.page=1;await loadBoard()});
$('#homeq').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();$('#homesearch').click()}});
$('#homeprev').onclick=()=>run(async()=>{if(board.page>1){board.page-=1;await loadBoard()}});
$('#homenext').onclick=()=>run(async()=>{board.page+=1;await loadBoard()});
if($('#useselected'))$('#useselected').hidden=true;
$('#clearselected').onclick=()=>{selected.clear();paintHome()};
$('#back').onclick=beginNew;$('#gohome').onclick=()=>{if(popupMode){parent.postMessage({type:'picking-back'},location.origin);return}if(boardMode){location.assign(boardReturnUrl());return}beginNew()};
function headDirty(){if(!current)return;titleTouched=$('#title').value!==suggestedTitle($('#date').value);if(current.id||current.sources.length||current.manual.length){dirty=true;return}dirty=$('#date').value!==today()||$('#title').value!==suggestedTitle(today())}
$('#title').oninput=headDirty;
$('#date').onchange=()=>{if(!titleTouched)$('#title').value=suggestedTitle($('#date').value);headDirty()};
