function changes(h){if(String(h.action).startsWith('Thunderbirdで送信画面を開いた')||String(h.action).startsWith('送信したことを記録')||String(h.action).startsWith('手配したことを記録'))return h.action;const a=JSON.parse(h.before_json),b=JSON.parse(h.after_json),result=[];for(const [k,label] of [['title','保存名'],['date','依頼日'],['status','状態'],['mailedAt','メール作成'],['sentAt','送信確認'],['arrangedAt','手配完了']])if((a[k]||'')!==(b[k]||''))result.push(`${label}：${a[k]||'未設定'} → ${b[k]||'未設定'}`);const before=new Map((a.rows||[]).map(r=>[r.key,r])),after=new Map((b.rows||[]).map(r=>[r.key,r]));for(const [k,r] of after){const old=before.get(k);if(!old)result.push(`追加：${r.requester} / ${r.customer} / ${r.name} × ${r.quantity}`);else for(const [field,label] of fields)if(String(old[field]??'')!==String(r[field]??''))result.push(`${r.customer} / ${r.name}：${label} ${old[field]??''} → ${r[field]??''}`)}for(const [k,r] of before)if(!after.has(k))result.push(`削除：${r.requester} / ${r.customer} / ${r.name}`);return result.join('\n')||'変更なし'}
