let carryOutRows=[];
function paintCarryOut(pack){const cols=[['from','出どころ'],['customer','顧客名'],['name','商品名'],['maker','メーカー'],['sku','品番'],['size','サイズ'],['condition','新古'],['quantity','数量'],['note','備考']];const fromSheet=(pack.sources||[]).flatMap(s=>(s.rows||[]).map(r=>({...r,from:s.number})));const fromInput=(pack.manual||[]).map(r=>({...r,from:'入力'}));carryOutRows=[...fromSheet,...fromInput];$('#carryprinted').hidden=!pack.printedAt;$('#carryprint').disabled=!carryOutRows.length;$('#carryoutlist').innerHTML=carryOutRows.length?'<table><thead><tr>'+cols.map(([,label])=>`<th>${label}</th>`).join('')+'<th>確認</th></tr></thead><tbody>'+carryOutRows.map(r=>'<tr>'+cols.map(([key])=>`<td>${esc(r[key])}</td>`).join('')+`<td class="checkcell"><input type="checkbox" data-carry-check="${esc(r.key)}" aria-label="確認" ${r.checked?'checked':''}></td></tr>`).join('')+'</tbody></table>':'<p>この日の管理担当持込はありません。</p>';$('#carryoutlist').querySelectorAll('[data-carry-check]').forEach(el=>el.onchange=()=>run(async()=>{const row=carryOutRows.find(r=>r.key===el.dataset.carryCheck);try{await api('/api/picking/carry-check',{date:$('#carrydate').value,key:el.dataset.carryCheck,checked:el.checked});if(row)row.checked=el.checked}catch(e){el.checked=!el.checked;throw e}}))}
$('#carryprint').onclick=()=>run(async()=>{const day=$('#carrydate').value;if(!day)throw Error('マーク出荷日を入れてください。');if(!carryOutRows.length)throw Error('この日の管理担当持込はありません。');const marked=await api('/api/picking/carry-print',{date:day});$('#carryprinted').hidden=false;await loadCarryMonth();const cols=[['from','出どころ'],['customer','顧客名'],['name','商品名'],['maker','メーカー'],['sku','品番'],['size','サイズ'],['condition','新古'],['quantity','数量'],['note','備考'],['checked','確認']];$('#printarea').innerHTML=`<p class="carryprinted">印刷済</p><h1>管理担当持込リスト</h1><p>${esc(day)}　${carryOutRows.length}明細　${esc(marked.printedBy||'')}</p><table><thead><tr>`+cols.map(([,label])=>`<th>${label}</th>`).join('')+'</tr></thead><tbody>'+carryOutRows.map(r=>'<tr>'+cols.map(([key])=>`<td>${key==='checked'?(r.checked?'済':''):key==='condition'?conditionCell(r):esc(r[key])}</td>`).join('')+'</tr>').join('')+'</tbody></table>';window.print()});
async function loadCarryOut(){const day=$('#carrydate').value;if(!day)throw Error('マーク出荷日を入れてください。');paintCarryOut(await api('/api/picking/carry-day',{date:day}))}
function paintCarryMonth(pack){const days=pack.days||[];const missing=pack.missing||0;const month=pack.month||$('#carrymonth').value;const by=Object.fromEntries(days.map(d=>[d.day,d]));const [y,m]=month.split('-').map(Number);const cells=Array(new Date(y,m-1,1).getDay()).fill(null);for(let d=1;d<=new Date(y,m,0).getDate();d++){const key=month+'-'+String(d).padStart(2,'0');cells.push({d,key,info:by[key]})}while(cells.length%7)cells.push(null);$('#carrymonthnote').textContent=days.length?(missing?`未印刷が${missing}日あります。赤が未印刷、緑が印刷済です。日付を押すとその日を開きます。`:'この月の持込は、すべて印刷済です。日付を押すとその日を開きます。'):'この月に、持込のある日はありません。';$('#carrymonthlist').innerHTML=`<div class="carrycal"><div class="calhead">${'日月火水木金土'.split('').map(w=>`<span>${w}</span>`).join('')}</div><div class="calgrid">${cells.map(c=>c?c.info?`<button type="button" class="calday ${c.info.printedAt?'done':'miss'}" data-open-carry="${esc(c.key)}" title="${c.info.count}明細">${c.d}<small>${c.info.printedAt?'済':'未'}</small></button>`:`<span class="calday quiet">${c.d}</span>`:'<span class="calblank"></span>').join('')}</div></div>`;$('#carrymonthlist').querySelectorAll('[data-open-carry]').forEach(b=>b.onclick=()=>{$('#carrydate').value=b.dataset.openCarry;run(loadCarryOut)})}
async function loadCarryMonth(){const month=$('#carrymonth').value;if(!month)throw Error('月を選んでください。');paintCarryMonth(await api('/api/picking/carry-month',{month}))}
