function carryKey(day){return 'carry:'+day+':'+crypto.randomUUID().replace(/-/g,'').slice(0,12)}
function paintCarryList(){const cols=[['customer','顧客名'],['name','商品名'],['maker','メーカー'],['sku','品番'],['size','サイズ'],['condition','新古'],['quantity','数量'],['note','備考']];const blocks=carryDays.map(d=>{const rows=(d.rows||[]).filter(r=>!r.listId);if(!rows.length)return '';return `<section class="carrydaylist"><div class="carrydayhead"><b>${esc(d.day)}</b><span>${rows.length}明細</span><button type="button" data-open-day="${esc(d.day)}">修正</button></div><div class="tablewrap"><table><thead><tr>`+cols.map(([,label])=>`<th>${label}</th>`).join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+cols.map(([key])=>`<td>${esc(r[key])}</td>`).join('')+'</tr>').join('')+'</tbody></table></div></section>'}).join('');$('#carryinlist').innerHTML=blocks||'<p>未出力の明細はありません。</p>';$('#carryinlist').querySelectorAll('[data-open-day]').forEach(b=>b.onclick=()=>{if(carryDirty&&!confirm('保存していない入力を破棄して、この日を開きますか？'))return;$('#carryindate').value=b.dataset.openDay;run(()=>loadCarryIn(true))})}
