function blankCarryRow(day){return {key:carryKey(day),customer:'',name:'',maker:'',sku:'',size:'',condition:'未指定',quantity:1,note:'',note2:'',requester:'マーク',origin:'交換依頼(他)'}}
function paintCarryIn(){const rows=carryDraft;$('#carryinrows').innerHTML=rows.length?rows.map(r=>{const locked=!!r.listId;const cell=(key,label)=>locked?`<span>${esc(r[key])}</span>`:key==='condition'?`<select data-carry="${esc(r.key)}" data-field="condition" aria-label="${label}">${['未指定','新品','中古'].map(v=>`<option ${r.condition===v?'selected':''}>${v}</option>`).join('')}</select>`:key==='quantity'?`<input data-carry="${esc(r.key)}" data-field="quantity" type="number" min="1" max="99999" step="1" aria-label="${label}" value="${esc(r.quantity)}">`:`<input data-carry="${esc(r.key)}" data-field="${key}" type="text" maxlength="${key==='note'||key==='note2'?1000:300}" aria-label="${label}" value="${esc(r[key])}">`;return `<div class="carryline${locked?' lockedline':''}">${[['customer','顧客名'],['name','商品名'],['maker','メーカー'],['sku','品番'],['size','サイズ'],['condition','新古'],['quantity','数量'],['note','備考']].map(([k,label])=>cell(k,label)).join('')}<span>${locked?'一覧済み':`<button type="button" class="drop" data-carry-remove="${esc(r.key)}">削除</button>`}</span></div>`}).join(''):'<p>行を追加して入力してください。保存すると下の一覧に追加されます。</p>';$('#carryinrows').querySelectorAll('[data-field]').forEach(el=>{const apply=()=>{const r=carryDraft.find(r=>r.key===el.dataset.carry);if(!r||r.listId)return;r[el.dataset.field]=el.value;carryDirty=true};el.oninput=apply;el.onchange=apply});$('#carryinrows').querySelectorAll('[data-carry-remove]').forEach(b=>b.onclick=()=>{if(!confirm('この行を削除しますか？'))return;carryDraft=carryDraft.filter(r=>r.key!==b.dataset.carryRemove);carryDirty=true;paintCarryIn()})}
async function loadCarryIn(open){const day=$('#carryindate').value;if(!day)throw Error('マーク出荷日を入れてください。');carryDoc=await api('/api/carry-input/load',{day});carryOpen=!!open;carryDraft=open?(carryDoc.rows||[]).filter(r=>!r.listId).map(r=>({...r})):[blankCarryRow(day)];carryDirty=false;paintCarryIn()}
