function savedMsg(s){const el=$('#savedmsg');if(el)el.textContent=s||''}
async function savedRun(fn){try{savedMsg('');await fn()}catch(e){savedMsg(e.message)}}
function askFrameDirty(){const frame=$('#savedframe');if(savedView!=='edit'||!frame||!frame.contentWindow||frame.src==='about:blank')return Promise.resolve(false);return new Promise(resolve=>{const timer=setTimeout(()=>{window.removeEventListener('message',onMsg);resolve(false)},700);function onMsg(e){if(e.origin!==location.origin||!e.data||e.data.type!=='picking-dirty')return;clearTimeout(timer);window.removeEventListener('message',onMsg);resolve(!!e.data.dirty)}window.addEventListener('message',onMsg);frame.contentWindow.postMessage({type:'picking-dirty?'},location.origin)})}
async function confirmSavedDiscard(action){if(savedView!=='edit')return true;if(!(await askFrameDirty()))return true;return confirm(`保存していない変更があります。破棄して${action}か？`)}
function savedRangeText(){const parts=[];if(savedQuery.from&&savedQuery.to)parts.push(`依頼日 ${savedQuery.from} ～ ${savedQuery.to}`);else if(savedQuery.from)parts.push(`依頼日 ${savedQuery.from} 以降`);else if(savedQuery.to)parts.push(`依頼日 ${savedQuery.to} まで`);if(savedQuery.q)parts.push(`検索「${savedQuery.q}」`);if(savedQuery.kind==='waiting')parts.push('保存済み・手配未完了');if(savedQuery.kind==='sent')parts.push('手配完了');if(!parts.length)return '条件は指定していません。';return parts.join('、')+'。依頼日で絞っています。指示書のマーク出荷日ではありません。'}
function paintSavedList(){if(!savedData)return;const counts=savedData.counts||{waiting:0,sent:0};$('#savedcounts').textContent=`保存済み・手配未完了 ${counts.waiting||0}件、手配完了 ${counts.sent||0}件。この件数は検索前です。削除したリストは含みません。メール待ちとメール不要の手配待ちを、手配未完了に含みます。`;$('#savedrange').textContent=savedData.total?`${savedRangeText()} 該当 ${savedData.total}件。`:`${savedRangeText()} 該当するリストはありません。`;const items=savedData.items||[];$('#savedrows').innerHTML=items.length?'<table class="lists"><thead><tr><th>リスト番号</th><th>保存名</th><th>依頼日</th><th>明細数</th><th>状態</th><th>手配</th><th></th></tr></thead><tbody>'+items.map(r=>{const phase=r.phase||'';const sent=r.sentAt?`${r.sentBy||'—'}　${r.sentAt}`:r.arrangedAt?`${r.arrangedBy||'—'}　${r.arrangedAt}`:'—';const open=!listFinished(r)&&r.status!=='取消'&&r.canEdit!==false;const canDelete=user&&user.role==='owner'&&open;return `<tr><td>${esc(r.number)}</td><td>${esc(r.title)}</td><td>${esc(r.date)||'—'}</td><td>${r.lines}明細</td><td>${esc(phase)}</td><td>${esc(sent)}</td><td><button type="button" data-saved-open="${r.id}">詳細を見る</button>${open?` <button type="button" data-saved-edit="${r.id}">編集・手配</button>`:''}${canDelete?` <button type="button" class="danger" data-saved-delete="${r.id}">削除</button>`:''}</td></tr>`}).join('')+'</tbody></table>':'<p class="emptyboard">該当するリストはありません。期間や状態を変えて検索できます。</p>';const size=savedData.pageSize||20;const start=items.length?(savedData.page-1)*size+1:0;const end=start?start+items.length-1:0;$('#savedpager').textContent=items.length?`${start}–${end}件目 / ${savedData.total}件`:`0件 / ${savedData.total||0}件`;$('#savedprev').disabled=savedData.page<=1;$('#savednext').disabled=savedData.page>=savedData.pages;$('#savedrows').querySelectorAll('[data-saved-open]').forEach(b=>b.onclick=()=>savedRun(()=>openSavedDetail(+b.dataset.savedOpen)));$('#savedrows').querySelectorAll('[data-saved-edit]').forEach(b=>b.onclick=()=>openSavedEdit(+b.dataset.savedEdit));$('#savedrows').querySelectorAll('[data-saved-delete]').forEach(b=>b.onclick=()=>deleteSaved(+b.dataset.savedDelete))}
async function loadSavedList(){savedData=await api('/api/picking/history',savedQuery);savedQuery.page=savedData.page;savedQuery.kind=savedData.kind||'';if($('#savedkind'))$('#savedkind').value=savedQuery.kind;paintSavedList()}
function showSavedListFace(){savedView='list';$('#savedlist').hidden=false;$('#saveddetail').hidden=true;$('#savededit').hidden=true;$('#savedback').hidden=true;$('#savedtitle').textContent='保存したピッキングリスト';const frame=$('#savedframe');if(frame)frame.src='about:blank'}
async function returnSavedList(){if(!(await confirmSavedDiscard('一覧へ戻ります')))return;showSavedListFace();await savedRun(loadSavedList)}
async function openSaved(kind){if($('#saveddialog').open&&savedView==='edit'&&!(await confirmSavedDiscard('一覧を切り替えます')))return;savedQuery.kind=kind==='waiting'?'waiting':'';savedQuery.page=1;if($('#savedkind'))$('#savedkind').value=savedQuery.kind;showSavedListFace();if(!$('#saveddialog').open)$('#saveddialog').showModal();await savedRun(loadSavedList);const q=$('#savedq');if(q)q.focus()}
function openSavedEdit(id){savedView='edit';savedDetail=null;$('#savedlist').hidden=true;$('#saveddetail').hidden=true;$('#savededit').hidden=false;$('#savedback').hidden=false;$('#savedtitle').textContent='保存したピッキングリストを編集';$('#savedframe').src='/picking?embed=1&popup=1&list='+id+'&t='+Date.now()}
async function openSavedDetail(id){savedDetail=await api('/api/picking/'+id);savedGroup='warehouse';savedView='detail';$('#savedlist').hidden=true;$('#savededit').hidden=true;$('#saveddetail').hidden=false;$('#savedback').hidden=false;$('#savedtitle').textContent='保存したピッキングリスト';paintSavedDetail();const history=await api('/api/picking/'+id+'/history');$('#sdlog').innerHTML=history.length?history.map(h=>`<details><summary>${esc(h.at)}　${esc(h.actor)}　${esc(h.action)}</summary><pre>${esc(changes(h))}</pre></details>`).join(''):'<p>変更履歴はありません。</p>'}
function paintSavedDetail(){const detail=savedDetail;if(!detail)return;const editableRow=!listFinished(detail)&&detail.status!=='取消'&&detail.canEdit!==false;$('#sdedit').hidden=!editableRow;$('#sdtitle').textContent=`${detail.number}　${detail.title||''}`;$('#sdphase').textContent=detail.phase||'';const rows=[...(detail.sources||[]).flatMap(s=>s.rows||[]),...(detail.manual||[])];const defs=[['warehouse','石狩倉庫'],['factory','発寒支店'],['carry','管理担当持込']];if(rows.some(r=>!r.stock))defs.push(['','在庫場所未設定']);if(!defs.some(([k])=>k===savedGroup))savedGroup='warehouse';$('#sdfacts').innerHTML=`<b>リスト番号</b><span>${esc(detail.number)}</span><b>保存名</b><span>${esc(detail.title)}</span><b>依頼日</b><span>${esc(detail.date)||'—'}（指示書のマーク出荷日ではありません）</span><b>状態</b><span>${esc($('#sdphase').textContent)}</span>`;$('#sdtabs').innerHTML=defs.map(([k,label])=>`<button type="button" data-group="${esc(k)}" class="${k===savedGroup?'current':''}">${label} ${rows.filter(r=>r.stock===k).length}明細</button>`).join('');$('#sdtabs').querySelectorAll('button').forEach(b=>b.onclick=()=>{savedGroup=b.dataset.group;paintSavedDetail()});const view=rows.filter(r=>r.stock===savedGroup);$('#sdrows').innerHTML=view.length?'<table><thead><tr>'+columns.map(([,label])=>`<th>${label}</th>`).join('')+'</tr></thead><tbody>'+view.map(r=>'<tr>'+columns.map(([k])=>`<td>${k==='condition'?conditionCell(r):esc(r[k])}</td>`).join('')+'</tr>').join('')+'</tbody></table>':'<p>この区分の明細はありません。表示しているのは、このリストに保存された内容です。</p>';const sent=detail.sentAt?`手配完了（メール送信）：${detail.sentBy||'—'}　${detail.sentAt}。この記録は、届けたことの自動確認ではありません。`:detail.arrangedAt?`手配完了（メール不要）：${detail.arrangedBy||'—'}　${detail.arrangedAt}。メール作成日時や送信日時は記録していません。`:'手配完了の記録はありません。';$('#sdmail').innerHTML=`<p>状態：${esc(detail.phase||'')}</p><p>${detail.mailedAt?`${esc(detail.mailedBy||'')} が ${esc(detail.mailedAt)} にメール作成画面を開いた記録があります。開いた記録であり、届いたことの確認ではありません。`:'メール作成の記録はありません。'}</p><p>${esc(sent)}</p>`;const output=detail.status==='確定';$('#sdoutput').innerHTML=output?'<button type="button" id="sdexcel">Excelを再出力</button><button type="button" id="sdprint">選択中の区分を再印刷</button><p class="hint">再出力と再印刷は、手配完了の記録も、元の指示書の作業状況も変えません。管理担当持込（出力）の印刷済みとは別です。</p>':'<p class="hint">削除したリストは出力できません。保存済みのリストは編集画面で保存してから出力してください。</p>';if(output){$('#sdexcel').onclick=()=>savedRun(downloadSaved);$('#sdprint').onclick=()=>savedRun(printSaved)}const canCancel=!!detail.id&&detail.status!=='取消'&&!listFinished(detail)&&detail.canEdit!==false;$('#sdcancel').hidden=!canCancel;$('#sdowner').hidden=true;$('#sdadmin').hidden=!canCancel}
async function downloadSaved(){const detail=savedDetail;const r=await fetch(`/api/picking/${detail.id}/xlsx`);if(!r.ok){const d=await r.json();throw Error(d.error)}const url=URL.createObjectURL(await r.blob());const a=document.createElement('a');a.href=url;a.download=`${detail.number}_${detail.date}.xlsx`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);savedMsg('Excelを再出力しました。送信確認や指示書の状態は変えていません。')}
async function printSaved(){const detail=savedDetail;const latest=await api('/api/picking/'+detail.id);if(latest.status!=='確定'||latest.version!==detail.version)throw Error('リストの状態が変わりました。詳細を開き直してください。');const rows=[...(latest.sources||[]).flatMap(s=>s.rows||[]),...(latest.manual||[])].filter(r=>r.stock===savedGroup);if(!rows.length)throw Error('選択中の区分には明細がありません。');$('#printarea').innerHTML=`<h1>${esc(groups[savedGroup]||'')} ピッキングリスト</h1><p>${esc(detail.number)}　依頼日 ${esc(detail.date)}　${esc(detail.title)}　${rows.length}明細</p><table><thead><tr>`+columns.map(([,label])=>`<th>${label}</th>`).join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+columns.map(([k])=>`<td>${k==='condition'?conditionCell(r):esc(r[k])}</td>`).join('')+'</tr>').join('')+'</tbody></table>';window.print()}
async function refreshAfterSaved(){const before=new Set(targetScope.map(s=>s.id));const snap=current&&$('#title')?{title:$('#title').value,date:$('#date').value}:null;await refreshBoard();if(!current)return;await loadCandidatePage(true);if(snap&&$('#title')){$('#title').value=snap.title;$('#date').value=snap.date}const after=new Set(targetScope.map(s=>s.id));const gone=[...before].filter(id=>!after.has(id)).length;const grown=[...after].filter(id=>!before.has(id)).length;if(gone||grown)message(`取り込み対象が変わりました。${gone?`別のリストに入った指示書が${gone}件あります。`:''}${grown?`新たに対象になった指示書が${grown}件あります。`:''}入力中の内容は残しています。`)}
async function closeSaved(){const dlg=$('#saveddialog');if(!dlg||!dlg.open)return;if(!(await confirmSavedDiscard('ポップアップを閉じます')))return;showSavedListFace();dlg.close();await refreshAfterSaved()}
window.addEventListener('message',e=>{if(e.origin!==location.origin||!e.data)return;if(e.data.type==='desk-refresh'&&window.parent&&window.parent!==window){parent.postMessage({type:'desk-refresh'},location.origin);return}if(popupMode&&e.data.type==='picking-dirty?'){e.source.postMessage({type:'picking-dirty',dirty:!!pendingNote()},e.origin);return}if(!popupMode&&e.data.type==='picking-back')returnSavedList();if(!popupMode&&e.data.type==='picking-close')closeSaved()});
if(popupMode)document.addEventListener('keydown',e=>{if(e.key!=='Escape')return;const sheets=$('#sheetsdialog');if(sheets&&sheets.open)return;e.preventDefault();parent.postMessage({type:'picking-close'},location.origin)});
if($('#opensaved'))$('#opensaved').onclick=()=>openSaved('');
$('#savedclose').onclick=()=>closeSaved();
$('#savedback').onclick=()=>returnSavedList();
$('#saveddialog').addEventListener('cancel',e=>{e.preventDefault();closeSaved()});
$('#saveddialog').addEventListener('click',e=>{if(e.target===$('#saveddialog'))closeSaved()});
$('#savedsearch').onclick=()=>savedRun(async()=>{savedQuery.q=$('#savedq').value.trim();savedQuery.from=$('#savedfrom').value;savedQuery.to=$('#savedto').value;savedQuery.kind=$('#savedkind').value;savedQuery.page=1;await loadSavedList()});
$('#savedclear').onclick=()=>savedRun(async()=>{savedQuery={kind:'',q:'',from:'',to:'',page:1};$('#savedq').value='';$('#savedfrom').value='';$('#savedto').value='';$('#savedkind').value='';await loadSavedList()});
$('#savedq').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();$('#savedsearch').click()}});
$('#savedprev').onclick=()=>savedRun(async()=>{if(savedQuery.page>1){savedQuery.page-=1;await loadSavedList()}});
$('#savednext').onclick=()=>savedRun(async()=>{savedQuery.page+=1;await loadSavedList()});
$('#sdedit').onclick=()=>{if(savedDetail)openSavedEdit(savedDetail.id)};
$('#sdcancel').onclick=()=>{if(!savedDetail||listFinished(savedDetail)||savedDetail.status==='取消')return;if(!confirmDelete(savedDetail))return;savedRun(async()=>{await api('/api/picking/cancel',{id:savedDetail.id,version:savedDetail.version,acknowledgeMailDiscard:!!(savedDetail.mailedAt||savedDetail.mailNeedsRecreate)});savedDetail=null;showSavedListFace();await loadSavedList();await refreshBoard();savedMsg('削除しました。一覧から外しました。入力中の新規作成は変えていません。')})};
$('#sdflag').onchange=()=>{if(!savedDetail)return;const status=$('#sdflag').value;if(status===savedDetail.status)return;if(!confirm(`確認用に、このリストを「${status}」に変えます。続けますか？`)){$('#sdflag').value=savedDetail.status;return}savedRun(async()=>{try{savedDetail=await api('/api/picking/flags',{id:savedDetail.id,version:savedDetail.version,status});await loadSavedList();paintSavedDetail();savedMsg(`確認用に${savedDetail.status}にしました。`)}catch(e){$('#sdflag').value=savedDetail.status;throw e}})};
run(async()=>{const me=await api('/api/me');user=me.user;const role=user?.role;if(!user||user.must_change||(carryKind==='in'&&role!=='owner'&&role!=='floor')||(carryKind==='out'&&role!=='owner'&&role!=='sales')||(!carryKind&&role!=='owner'&&role!=='floor')){location.replace('/');return}if(role==='owner')document.querySelectorAll('aside .nav[data-view="all"],aside .nav[data-view="draft"]').forEach(n=>n.hidden=false);$('#who').textContent=user.name;try{$('#mailto').value=localStorage.getItem('warehouse-mailto:'+user.id)||''}catch{};if(carryKind==='in'){$('#library').hidden=true;$('#editor').hidden=true;$('#carrydesk').hidden=true;$('#carryin').hidden=false;document.querySelector('header strong').textContent='管理担当持込(入力)';$('#carryindate').value=today();await loadCarryList();await loadCarryIn();return}if(carryKind==='out'){$('#library').hidden=true;$('#editor').hidden=true;$('#carryin').hidden=true;$('#carrydesk').hidden=false;$('#carrydate').value=today();$('#carrymonth').value=today().slice(0,7);document.querySelector('header strong').textContent='管理担当持込(出力)';await loadCarryMonth();await loadCarryOut();return}await loadBoard();if(popupMode){const id=Number(pageQuery.get('list'));if(!id){parent.postMessage({type:'picking-back'},location.origin);return}await open(await api('/api/picking/'+id));message('保存したピッキングリストです。うしろの新規作成の入力とは別です。送信前なら、ここで修正して保存できます。');return}if(boardMode){await openFromBoard();return}await openBlank()});
